const ROUTE = '/services/publication-support/peer-review-pre-submission/';
const meta = routeByPath.get(ROUTE)!;

export const metadata: Metadata = {
  title: meta.title,
  description: meta.description,
  alternates: { canonical: SITE_URL + ROUTE },
  openGraph: {
    title: meta.title,
    description: meta.description,
    url: SITE_URL + ROUTE,
    type: 'website',
    images: ["https://pubrica.com/share/pubrica-card.jpg"],
  },
};

const schema = [{"@context":"https://schema.org","@type":"Service","name":"Pre-Submission Peer Review Service","serviceType":"Pre-submission peer review and manuscript assessment","provider":{"@type":"Organization","name":"Pubrica","url":"https://pubrica.com/"},"url":"https://pubrica.com/services/publication-support/peer-review-pre-submission/","description":"Reviewer comments graded critical, major and minor with a worked reporting checklist — the objection heard before an editor's reviewer makes it.","areaServed":"Worldwide","audience":{"@type":"Audience","audienceType":"Researchers, PhD scholars, research institutions, medical writers and life-science teams"}},{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What is pre-submission peer review for research manuscripts?","acceptedAnswer":{"@type":"Answer","text":"An expert in your field reviews the manuscript before you send it to a journal, against the same criteria that journal gives its own reviewers — methodology, reporting, clarity and ethics. You get the objections in writing while you can still act on them, rather than after a decision."}},{"@type":"Question","name":"How does pre-submission peer review differ from journal peer review?","acceptedAnswer":{"@type":"Answer","text":"Journal peer review decides whether you are published. Pre-submission review has no such power and no such stake — its only purpose is to improve the manuscript. That changes what you get: a journal reviewer writes for the editor, a pre-submission reviewer writes for you, so the comments come with the action that answers them."}},{"@type":"Question","name":"Can pre-submission peer review increase my chance of acceptance?","acceptedAnswer":{"@type":"Answer","text":"It removes avoidable rejections. It cannot make an underpowered study adequate or a familiar finding novel, and anyone promising otherwise is selling something. What it does is stop sound work being rejected for a missing effect estimate, an unreported interaction test or a reporting checklist nobody filled in."}},{"@type":"Question","name":"What mistakes does pre-submission review catch most often?","acceptedAnswer":{"@type":"Answer","text":"In order of frequency: claims the data does not reach, effect estimates reported without confidence intervals, subgroups read as signals without an interaction test, reporting checklists not followed, and declarations missing — ethics, consent, registration, conflicts, and increasingly AI use. Four of those five are fixable in a day."}},{"@type":"Question","name":"What feedback should I expect?","acceptedAnswer":{"@type":"Answer","text":"Written comments, each graded critical, major or minor, attributed to the reviewer who raised it and tied to the passage it refers to, with the specific action that answers it. Plus a worked reporting checklist and a response plan ordered by what blocks submission. A typical review returns 15 to 25 comments."}},{"@type":"Question","name":"Who reviews my manuscript?","acceptedAnswer":{"@type":"Answer","text":"A Pubrica subject expert who holds a doctorate or clinical post in your field and reviews for journals in it. Where the work is statistical, a second reviewer reads the analysis independently. You are told who they are and what their standing is — anonymous feedback is difficult to weigh."}},{"@type":"Question","name":"Do you use AI to review the manuscript?","acceptedAnswer":{"@type":"Answer","text":"No. Software is used for what software is good at — reference resolution, similarity screening, checklist coverage. Every comment in the report is written by a Pubrica subject expert. A model can tell you a sentence is unclear; it cannot tell you that your interaction test is missing and that this particular journal's reviewers always ask for it."}},{"@type":"Question","name":"What documents can be reviewed?","acceptedAnswer":{"@type":"Answer","text":"Research articles, review articles, case reports, systematic reviews and meta-analyses, conference papers, grant proposals, and theses or dissertations being turned into papers. The review is run against the target journal or funder's requirements, so tell us which one."}},{"@type":"Question","name":"How long does journal peer review itself take?","acceptedAnswer":{"@type":"Answer","text":"Weeks to months, and it varies more by journal than by field. Time to first decision is worth checking before you submit rather than after; it is one of the criteria our journal selection service scores journals on."}},{"@type":"Question","name":"How do I make sure the manuscript meets journal ethical guidelines?","acceptedAnswer":{"@type":"Answer","text":"Ethics committee approval and its reference number stated, informed consent described, the trial or protocol registered prospectively, competing interests and funding declared, authorship meeting ICMJE criteria, and any generative AI use disclosed. The review checks each against what your target journal requires, because the requirements differ."}},{"@type":"Question","name":"How do I prepare a cover letter?","acceptedAnswer":{"@type":"Answer","text":"State what the study asked and found in two sentences, why it matters to that journal's readership specifically, that the work is original and not under consideration elsewhere, and any competing interests. Editors screen cover letters quickly; the useful ones say why this journal rather than any journal. The Comprehensive package drafts it."}},{"@type":"Question","name":"What should I check before submitting?","acceptedAnswer":{"@type":"Answer","text":"Scope fit, article type, word and abstract limits, reference style, figure formats, the reporting checklist uploaded, ethics and consent stated, registration in the abstract where required, declarations complete, and every reference resolving to what it is cited for. Editorial staff return manuscripts on this list more often than authors expect."}},{"@type":"Question","name":"What do journal reviewers actually look for?","acceptedAnswer":{"@type":"Answer","text":"Whether the method can answer the question, whether the results support the conclusions, whether it adds to what is already known, and whether it is reported well enough to be believed and repeated. Novelty matters less than authors expect; reachability of the conclusions matters more."}}]},{"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://pubrica.com/"},{"@type":"ListItem","position":2,"name":"Publication support","item":"https://pubrica.com/services/publication-support/"},{"@type":"ListItem","position":3,"name":"Pre-submission peer review","item":"https://pubrica.com/services/publication-support/peer-review-pre-submission/"}]}];

